    public static Optional<DevotionalItem> findChalisa(String slug) {
        return chalisas().stream().filter(c -> c.slug().equals(slug)).findFirst();
    }

    public static Optional<DevotionalItem> findBhajan(String slug) {
        return bhajans().stream().filter(b -> b.slug().equals(slug)).findFirst();
    }

    private DevotionalCatalog() {}
